/**
 * Undoes a deletion still inside its grace window. There is no `Actor` here —
 * a deleted workspace has no session that resolves to one — so the caller is
 * identified by user id and the role check is built from their membership row
 * directly, which deletion never touches.
 */
export async function restoreOrganization(
  userId: UserId,
  orgId: OrgId,
): Promise<Organization> {
  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);

  const member = requireFound(
    await memberRepo.findMember(orgId, userId),
    "Organization",
    orgId,
  );

  if (org.archivedAt === null) {
    return org;
  }

  const deletedAtMs = new Date(org.archivedAt).getTime();
  const windowClosesAtMs = deletedAtMs + DELETED_WORKSPACE_RETENTION_DAYS * MS_PER_DAY;

  if (Date.now() >= windowClosesAtMs) {
    throw new NotFoundError("Organization", orgId);
  }

  const actor: Actor = { userId, orgId, role: member.role };
  assertCan(actor, "org:restore", orgResource(orgId));

  const restored = await orgRepo.restoreOrg(orgId);

  await emit("organization.restored", {
    ...envelope(orgId, userId),
    slug: restored.slug,
  });

  return restored;
}

